var s=document.createElement('style');s.id='pk-podglad';s.textContent="/* ===== Zmiana 1: sekcja \u201ePorozmawiajmy!\u201d + mapa lokalizacji (be\u017cowy pas nad stopk\u0105, na ka\u017cdej stronie) ===== */\n\n/* sekcja: r\u00f3wne odst\u0119py g\u00f3ra/d\u00f3\u0142 */\n.site-above-footer-wrap[data-section=\"section-above-footer-builder\"] {\n  padding: 96px 0 !important;\n}\n\n/* kontener: max 1200 px tre\u015bci, 2 kolumny 380 px + reszta */\n.site-above-footer-wrap[data-section=\"section-above-footer-builder\"] .ast-builder-grid-row {\n  grid-template-columns: 380px 1fr !important;\n  column-gap: 64px !important;\n  max-width: 1264px !important;\n  margin: 0 auto !important;\n  padding-left: 32px !important;\n  padding-right: 32px !important;\n  align-items: stretch !important;\n}\n\n/* lewa kolumna wype\u0142nia ca\u0142\u0105 wysoko\u015b\u0107 (potrzebne do wy\u015brodkowania ucha) */\n.site-footer-above-section-1,\n.site-footer-above-section-1 .footer-widget-area,\n.site-footer-above-section-1 .widget,\n.site-footer-above-section-1 .custom-html-widget {\n  height: 100%;\n  margin: 0 !important;\n}\n.site-footer-above-section-2 .widget,\n.site-footer-above-section-2 .footer-widget-area { margin: 0 !important; width: 100%; }\n\n/* nag\u0142\u00f3wki */\n.pk-h2 {\n  font-family: \"Instrument Serif\", serif !important;\n  font-weight: 400 !important;\n  font-size: 62px !important;\n  line-height: 1.05 !important;\n  color: #191919 !important;\n  margin: 0 !important;\n}\n.pk-h2--mapa { font-size: 52px !important; margin-bottom: 10px !important; }\n\n/* lewa kolumna */\n.pk-lewa {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  text-align: center;\n  height: 100%;\n}\n.pk-blok {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 36px;\n  padding-top: 24px;\n}\n.pk-ucho { width: 150px; height: auto; display: block; }\n.pk-dane a {\n  display: block;\n  font-family: \"DM Mono\", monospace;\n  font-size: 17px;\n  line-height: 1.9;\n  letter-spacing: .1em;\n  color: #b44430 !important;\n  text-decoration: none !important;\n}\n.pk-dane a:hover { text-decoration: underline !important; }\n\n/* prawa kolumna */\n.pk-sub {\n  font-family: \"DM Mono\", monospace;\n  font-size: 13px;\n  letter-spacing: .2em;\n  text-transform: uppercase;\n  color: rgba(25, 25, 25, .6);\n  margin: 0 0 28px !important;\n}\n.pk-mapa-img {\n  display: block;\n  width: 100% !important;\n  height: auto !important;\n  max-width: none !important;\n  border: 0; border-radius: 0; box-shadow: none;\n}\n\n/* tablet i telefon: jedna kolumna */\n@media (max-width: 921px) {\n  .site-above-footer-wrap[data-section=\"section-above-footer-builder\"] {\n    padding: 56px 0 !important;\n  }\n  .site-above-footer-wrap[data-section=\"section-above-footer-builder\"] .ast-builder-grid-row {\n    grid-template-columns: 1fr !important;\n    row-gap: 56px !important;\n    padding-left: 20px !important;\n    padding-right: 20px !important;\n  }\n  .pk-h2 { font-size: 48px !important; }\n  .pk-h2--mapa { font-size: 40px !important; }\n  .pk-mapa { text-align: center; }\n  .pk-blok { gap: 28px; }\n  .pk-ucho { width: 120px; }\n}\n\n/* ===== Zmiana 2: mniejsza bia\u0142a przerwa pod wizualizacj\u0105 dziedzi\u0144ca (\"O inwestycji\") =====\n   Ukrywa blok Odst\u0119p (101 px) pod sekcj\u0105 z wizualizacj\u0105 (obraz wp-image-657).\n   Zostaje sam dolny padding sekcji (~71 px) \u2013 tyle samo co odst\u0119p nad tekstem.\n   Alternatywa bez CSS: w edytorze strony g\u0142\u00f3wnej usun\u0105\u0107 blok \"Odst\u0119p\" 101 px pod t\u0105 sekcj\u0105. */\n.entry-content > .wp-block-columns:has(.wp-image-657) + .wp-block-spacer {\n  display: none !important;\n}\n\n/* ===== Zmiana 4: strona \"O nas\" \u2013 zdj\u0119cia sekcji przechodz\u0105 p\u0142ynnie jedno w drugie =====\n   Usuwa pionowy odst\u0119p (2 \u00d7 ~71 px) mi\u0119dzy kolejnymi sekcjami (zdj\u0119cie prawe / lewe / prawe).\n   Zostaje odst\u0119p nad pierwsz\u0105 i pod ostatni\u0105 sekcj\u0105. Dotyczy tylko strony \"O nas\" (page-id-18). */\nbody.page-id-18 .entry-content > .wp-block-columns.alignfull {\n  padding-top: 0 !important;\n  padding-bottom: 0 !important;\n}\nbody.page-id-18 .entry-content > .wp-block-columns.alignfull:first-child {\n  padding-top: var(--wp--preset--spacing--80) !important;\n}\nbody.page-id-18 .entry-content > .wp-block-columns.alignfull:last-child {\n  padding-bottom: var(--wp--preset--spacing--80) !important;\n}\n\n/* ===== Zmiana 5: ostre kraw\u0119dzie na ca\u0142ej stronie (zamiast zaokr\u0105gle\u0144) =====\n   Wszystkie elementy na wszystkich podstronach: okno lokalu i jego przycisk \u00d7, pola formularzy,\n   przyciski filtr\u00f3w i prze\u0142\u0105cznik na stronach Lokale/Gastro, karty listy lokali, ikona Instagrama itd.\n   Zostaj\u0105 okr\u0105g\u0142e tylko wska\u017aniki \u0142adowania (formularz, filtry), kropki w ikonie filtr\u00f3w i pola wyboru typu \u201eradio\u201d. */\nbody *,\nbody *::before,\nbody *::after {\n  border-radius: 0 !important;\n}\nbody .wpcf7-spinner,\nbody .wpcf7-spinner::before,\nbody .wpc-spinner::after,\nbody [class*=\"wpc-icon-line\"]::after,\nbody input[type=\"radio\"] {\n  border-radius: 50% !important;\n}\n\n/* ===== Zmiana 6: Gastro i Lokale \u2013 selektor lokali jak na stronie g\u0142\u00f3wnej =====\n   T\u0142o za selektorem w bieli strony (#f8f6f2), nie be\u017cowe.\n   Linie paska i nieaktywny przycisk widoku dostaj\u0105 be\u017c, bo bia\u0142e znikn\u0119\u0142yby na bia\u0142ym tle.\n   Klas\u0119 pk-pas-lokali nadaje si\u0119 blokowi Grupa, w kt\u00f3rym siedzi selektor (patrz INSTRUKCJA, zmiana 6). */\n.pk-pas-lokali {\n  background: #f8f6f2;\n  margin-left: calc(50% - 50vw) !important;\n  margin-right: calc(50% - 50vw) !important;\n  padding: 40px;\n}\n.pk-pas-lokali #pankiewicza-selector {\n  max-width: 1360px;\n  margin: 0 auto;\n}\n.pk-pas-lokali .nav-bar {\n  border-top-color: #d3c7af !important;\n  border-bottom-color: #d3c7af !important;\n}\n.pk-pas-lokali .toggle-btn:not(.active) {\n  background: #ebe5da !important;\n}\n@media (max-width: 921px) {\n  .pk-pas-lokali { padding: 24px 16px; }\n}\n\n/* ===== Zmiana 7: stopka (czarna) \u2013 nowy uk\u0142ad =====\n   3 kolumny: logotyp + adres + social | \u201eZaufali nam:\u201d + logotypy partner\u00f3w | \u201eZa projekt odpowiada:\u201d + logo GJ5.\n   Pod spodem cienka linia i wiersz praw autorskich. Logotypy partner\u00f3w bez zmian. */\n.site-primary-footer-wrap[data-section=\"section-primary-footer-builder\"] {\n  padding: 80px 0 56px !important;\n  background: #191919 !important;\n}\n.site-primary-footer-wrap[data-section=\"section-primary-footer-builder\"] .ast-builder-grid-row {\n  grid-template-columns: 1fr 2.4fr 1fr !important;\n  column-gap: 32px !important;\n  max-width: 1360px !important;\n  margin: 0 auto !important;\n  padding: 0 40px !important;\n  align-items: start !important;\n}\n.site-primary-footer-wrap .site-footer-section {\n  align-items: center !important;\n  justify-content: flex-start !important;\n}\n.site-primary-footer-wrap .footer-widget-area,\n.site-primary-footer-wrap .footer-widget-area .widget {\n  width: 100%;\n  text-align: center !important;\n  margin: 0 !important;\n}\n/* nag\u0142\u00f3wki kolumn: \u201eZaufali nam:\u201d, \u201eZa projekt odpowiada:\u201d \u2013 DM Mono 16 px wg brand manualu (rozdz. 2.2:\n   kr\u00f3tkie formy DM Mono, kapitaliki, rozstrzelone). Rozstrzelenie 0.2em = to samo co etykiety sekcji\n   na stronie ([ O INWESTYCJI ]: 16 px, uppercase, 20%). Zast\u0119puje dotychczasowe -2px.\n   \u201eZa projekt odpowiada:\u201d to podpis jak \u201eZaufali nam:\u201d, wi\u0119c dostaje ten sam styl\n   (zamiast nag\u0142\u00f3wka Instrument Serif 36 px dawnego \u201eInwestor\u201d). */\n.site-primary-footer-wrap h2,\n.site-primary-footer-wrap h3 {\n  text-align: center !important;\n  margin: 0 0 28px !important;\n}\n.site-primary-footer-wrap .site-footer-primary-section-2 h3,\n.site-primary-footer-wrap .site-footer-primary-section-3 h2 {\n  font-family: \"DM Mono\", monospace !important;\n  font-size: 16px !important;\n  font-weight: 400 !important;\n  line-height: 1.5 !important;\n  letter-spacing: .2em !important;\n  text-transform: uppercase !important;\n}\n/* logotyp Pankiewicza w kolumnie 1 */\n.site-primary-footer-wrap .pk-stopka-logo {\n  display: block;\n  width: 290px;\n  max-width: 100%;\n  height: auto;\n  margin: 0 auto 26px;\n}\n/* adres \u2013 DM Mono jak dot\u0105d (14 px), wy\u015brodkowany, kapitaliki + rozstrzelenie 0.2em wg brand manualu */\n.site-primary-footer-wrap .site-footer-primary-section-1 p {\n  text-align: center !important;\n  margin: 0 !important;\n  line-height: 1.8 !important;\n  letter-spacing: .2em !important;\n  text-transform: uppercase !important;\n}\n/* ikony social */\n.site-primary-footer-wrap .wp-block-social-links {\n  justify-content: center !important;\n  gap: 28px !important;\n  margin: 26px 0 0 !important;\n}\n.site-primary-footer-wrap .wp-social-link {\n  background: none !important;\n  color: #f8f6f2 !important;\n}\n.site-primary-footer-wrap .wp-social-link a { padding: 0 !important; }\n.site-primary-footer-wrap .wp-social-link svg { width: 32px !important; height: 32px !important; }\n/* logotypy partner\u00f3w */\n.site-primary-footer-wrap .p_black-logo-invert {\n  justify-content: center !important;\n  align-items: center !important;\n  gap: 30px !important;\n  flex-wrap: nowrap !important;\n  background: transparent !important;\n}\n.site-primary-footer-wrap .p_black-logo-invert > * {\n  flex: 0 1 108px !important;\n  width: 108px !important;\n  margin: 0 !important;\n}\n.site-primary-footer-wrap .p_black-logo-invert img {\n  width: 100% !important;\n  height: auto !important;\n}\n/* logo GJ5 */\n.site-primary-footer-wrap .site-footer-primary-section-3 img {\n  width: 72px !important;\n  height: auto !important;\n  margin: 0 auto;\n  display: block;\n}\n.site-primary-footer-wrap .site-footer-primary-section-3 figure { margin: 0 auto !important; }\n/* wiersz praw autorskich */\n.site-below-footer-wrap[data-section=\"section-below-footer-builder\"] {\n  border-top: 1px solid rgba(248, 246, 242, .55) !important;\n  padding: 22px 0 26px !important;\n  background: #191919 !important;\n}\n.site-below-footer-wrap .ast-footer-copyright,\n.site-below-footer-wrap .ast-footer-copyright p {\n  text-align: center !important;\n  margin: 0 !important;\n}\n/* prawa autorskie \u2013 DM Mono jak dot\u0105d, kapitaliki + rozstrzelenie 0.2em wg brand manualu (rozmiar 14 px, \u017ceby wiersz si\u0119 zmie\u015bci\u0142) */\n.site-below-footer-wrap .ast-footer-copyright p {\n  font-size: 14px !important;\n  letter-spacing: .2em !important;\n  text-transform: uppercase !important;\n}\n@media (max-width: 921px) {\n  .site-primary-footer-wrap[data-section=\"section-primary-footer-builder\"] .ast-builder-grid-row {\n    grid-template-columns: 1fr !important;\n    row-gap: 56px !important;\n    padding: 0 20px !important;\n  }\n  .site-primary-footer-wrap .p_black-logo-invert { gap: 24px !important; flex-wrap: wrap !important; }\n}\n\n/* ===== Zmiana 8: wi\u0119ksze nag\u0142\u00f3wki podstron (Lokale, Gastro, Aktualno\u015bci, Events, Kontakt, O nas\u2026) =====\n   Tytu\u0142 strony (h1.entry-title) z 32 px na 80 px \u2013 wi\u0119kszy ni\u017c nag\u0142\u00f3wki sekcji (60 px), \u017ceby by\u0142 najwa\u017cniejszy na stronie. */\nh1.entry-title {\n  font-size: 80px !important;\n  line-height: 1.05 !important;\n  letter-spacing: -0.01em !important;\n  margin-bottom: 32px !important;\n}\n@media (max-width: 921px) {\n  h1.entry-title { font-size: 60px !important; margin-bottom: 24px !important; }\n}\n@media (max-width: 544px) {\n  h1.entry-title { font-size: 44px !important; margin-bottom: 20px !important; }\n}\n\n/* ===== Zmiana 9: strona g\u0142\u00f3wna \u2013 mniejsza bia\u0142a przerwa mi\u0119dzy galeri\u0105 z budowy (be\u017cowy pas) a sekcj\u0105 \u201eApartamenty\u201d =====\n   Ukrywa blok Odst\u0119p (100 px) pod galeri\u0105. Zostaje g\u00f3rny padding sekcji (~71 px) \u2013 tak samo jak przy zmianie 2. */\n.entry-content > .galeria-scroll + .wp-block-spacer {\n  display: none !important;\n}\n\n/* ===== Zmiana 10: strona g\u0142\u00f3wna \u2013 sekcja \u201eAktualno\u015bci / Pankiewicza na codzie\u0144\u201d (niebieskie t\u0142o) =====\n   Nad tre\u015bci\u0105 by\u0142o 140 px pustego niebieskiego (padding 40 px + blok Odst\u0119p 100 px). Odst\u0119p skr\u00f3cony do 40 px \u2192 razem 80 px. */\n.uagb-block-5584c2bc > .wp-block-spacer:first-child {\n  height: 40px !important;\n}\n";document.head.appendChild(s);
