/* Zmiana 6: Gastro i Lokale – selektor lokali taki sam jak na stronie głównej */
(function(){
  var path = location.pathname.replace(/\/+$/,'/');
  var START = {'/gastro/':{view:'map',filter:'Lokal usługowy'}, '/lokale/':{view:'map',filter:'Apartament'}}[path];
  if (!START) return;
  var old = document.getElementById('pankiewicza-selector');
  if (!old) return;
  fetch('/', {credentials:'same-origin'}).then(function(r){return r.text();}).then(function(html){
    var doc = new DOMParser().parseFromString(html, 'text/html');
    var parter = doc.getElementById('parter');
    var sel = doc.getElementById('pankiewicza-selector');
    if (!parter || !sel) return;
    var css = Array.prototype.map.call(parter.querySelectorAll('style'), function(s){return s.textContent;}).join('\n');
    var js = Array.prototype.map.call(parter.querySelectorAll('script'), function(s){return s.textContent;}).join('\n');
    // stary CSS selektora z tej strony – usuwamy, żeby nie nadpisywał nowego wyglądu
    Array.prototype.forEach.call(document.querySelectorAll('.entry-content > style'), function(s){
      if (/toggle-btn|facade-wrapper|unit-zone/.test(s.textContent)) s.remove();
    });
    var st = document.createElement('style'); st.id = 'pk-selektor-css'; st.textContent = css; document.head.appendChild(st);
    sel.setAttribute('data-start-view', START.view);
    sel.setAttribute('data-start-filter', START.filter);
    var band = document.createElement('div'); band.className = 'pk-pas-lokali';
    band.appendChild(document.importNode(sel, true));
    old.replaceWith(band);
    var body = js.replace(/document\.addEventListener\(\s*'DOMContentLoaded'\s*,\s*\(\)\s*=>\s*\{/, '(() => {').replace(/\}\);\s*$/, '})();');
    try { new Function(body)(); } catch(e) { console.error('Podgląd zmian – selektor:', e); }
  });
})();

